import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.BsgK4TUM.js";const k=JSON.parse('{"title":"Events","description":"","frontmatter":{},"headers":[],"relativePath":"developers/events.md","filePath":"developers/events.md"}'),n={name:"developers/events.md"};function o(r,e,d,c,l,h){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h1><p>The Community Store also includes &#39;Events&#39; - these are hooks that <a href="https://documentation.concretecms.org/developers/framework/application-events/hooking-application-events" target="_blank" rel="noreferrer">can be subscribed to with custom code</a>, allowing additional processing to take place.</p><p>An example might be that you wish to communicate with a separate warehouse database/API to determine current stock levels or prices. By subscribing to the <code>on_community_store_product_add</code> and <code>on_community_store_product_update</code> events, you could create code that takes the product SKU, looks it up in the external database and then updates the product accordingly.</p><p>Another usage example is for when you need to do some additional processing when an order is placed. The example might be that you may need to send an email to a supplier when a particular product is purchased. Events allow such functionality to be added through additional Concrete CMS add-ons.</p><p><a href="https://github.com/concretecms-community-store/community_store_event_example" target="_blank" rel="noreferrer">An example package showing how to respond to Community Store events is available on github</a>.</p><h2 id="order-events" tabindex="-1">Order events <a class="header-anchor" href="#order-events" aria-label="Permalink to &quot;Order events&quot;">​</a></h2><ul><li><code>on_community_store_order_created</code> - when an order is first created, before it is completed (for external payment methods, this is before the customer is sent to the payment gateway)</li><li><code>on_community_store_order</code> - when a new order is placed</li><li><code>on_community_store_order_status_update</code> - when an order changes status (but not initially)</li><li><code>on_community_store_before_payment_complete</code> - just before an order is marked as paid</li><li><code>on_community_store_payment_complete</code> - when an order is marked as paid (via a gateway or manually)</li><li><code>on_community_store_order_cancelled</code> - when an order is cancelled via the Dashboard</li><li><code>on_before_community_store_order_notification_emails</code> - before order notification emails are sent. The event&#39;s <code>getNotificationEmails()</code> and <code>setNotificationEmails()</code> methods can be used to change who receives them</li><li><code>on_community_store_before_user_add</code> - before a user account is created for a customer on purchase. A listener can call <code>updateUserData()</code> on the event with an array containing <code>uName</code> and/or <code>uPassword</code> to change the new user&#39;s username or password</li></ul><h2 id="product-events" tabindex="-1">Product events <a class="header-anchor" href="#product-events" aria-label="Permalink to &quot;Product events&quot;">​</a></h2><ul><li><code>on_community_store_product_add</code> - when a new product is added</li><li><code>on_community_store_product_update</code>- when an existing product is updated</li><li><code>on_community_store_product_delete</code> - when a product is deleted</li><li><code>on_community_store_product_duplicate</code> - when a product is duplicated</li></ul><h2 id="cart-events" tabindex="-1">Cart events <a class="header-anchor" href="#cart-events" aria-label="Permalink to &quot;Cart events&quot;">​</a></h2><ul><li><code>on_community_store_cart_action</code> - any time an action with a cart is performed</li><li><code>on_community_store_cart_pre_add</code></li><li><code>on_community_store_cart_post_add</code></li><li><code>on_community_store_cart_pre_update</code></li><li><code>on_community_store_cart_post_update</code></li><li><code>on_community_store_cart_pre_remove</code></li><li><code>on_community_store_cart_post_remove</code></li><li><code>on_community_store_cart_pre_clear</code></li><li><code>on_community_store_cart_post_clear</code></li><li><code>on_community_store_cart_get</code> - when the cart is loaded. The event&#39;s data contains the <code>cart</code> and <code>discounts</code>, and a listener can replace them with <code>setUpdatedCart()</code> and <code>setUpdatedDiscounts()</code></li></ul><h2 id="payment-events" tabindex="-1">Payment events <a class="header-anchor" href="#payment-events" aria-label="Permalink to &quot;Payment events&quot;">​</a></h2><ul><li><code>on_community_store_payment_methods_get</code> - when the payment methods available in the checkout are determined. A listener can change the list with <code>getMethods()</code> and <code>setMethods()</code>, calling <code>setChanged()</code> to apply the changes</li></ul><h2 id="tax-events" tabindex="-1">Tax events <a class="header-anchor" href="#tax-events" aria-label="Permalink to &quot;Tax events&quot;">​</a></h2><ul><li><code>on_community_store_tax_calculate</code> - when a tax rate is calculated. A listener can use <code>getTaxRate()</code> to inspect the rate, and <code>setUpdatedRate()</code> and <code>setUpdatedLabel()</code> to change the rate and label applied</li></ul><h2 id="checkout-events" tabindex="-1">Checkout events <a class="header-anchor" href="#checkout-events" aria-label="Permalink to &quot;Checkout events&quot;">​</a></h2><ul><li><code>on_community_store_checkout_request</code> - when any checkout page action is requested (e.g. <code>view</code>, <code>submit</code>, <code>external</code>, <code>updater</code>), before the action runs</li></ul><p>The checkout event provides <code>getAction()</code> and <code>getParameters()</code>. A listener can call <code>setResponse()</code> with a response (such as a redirect) to return it instead of running the checkout action, for example:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Events</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">addListener</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;on_community_store_checkout_request&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ($event) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ($someCondition) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        $event</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setResponse</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Concrete\\Core\\Routing\\Redirect</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">to</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/somewhere-else&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">));</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><ul><li><code>on_community_store_checkout_complete_view</code> - when the order complete page is viewed, after the cart has been cleared</li></ul><p>The complete view event provides <code>getOrder()</code> and <code>getController()</code>. The controller can be used to set view variables or add header/footer items, for example to output conversion tracking scripts. <code>getOrder()</code> returns null when an administrator views the page without having placed an order. As the page can be refreshed, the event can fire more than once for the same order. <code>setResponse()</code> can also be used to return a different response.</p><ul><li><code>on_community_store_checkout_validate</code> - when billing or shipping details are submitted during checkout, after the built-in validation and before the details are saved</li></ul><p>The validate event provides <code>getErrors()</code>, <code>getData()</code> (the submitted form data, e.g. <code>store-checkout-billing-zip</code>, <code>store-checkout-shipping-country</code>), <code>getAddressType()</code> (<code>billing</code> or <code>shipping</code>) and <code>getController()</code>. Adding an error to the error list prevents the details from being saved and displays the error to the customer, for example:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Events</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">addListener</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;on_community_store_checkout_validate&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ($event) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    $data </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $event</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getData</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ($event</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getAddressType</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;shipping&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $data[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;store-checkout-shipping-country&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;GB&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        $event</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getErrors</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;We can only deliver within the UK&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">));</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>This event validates the checkout form steps only; it is not re-run when the order is submitted, so it should not be relied upon as the sole enforcement of a rule. VAT number validation takes place separately, after this event.</p><p>When these events are fired, the event object passed includes the order or product it relates to. In the case of when a product is updated, or duplicated, the event object includes both the before and after products.</p><p>The <code>on_community_store_order_status_update</code> event also includes the previous status of the order.</p><p>The community_store_event_examples package includes sample code as to how to subscribe to and use the data from all the events above - <a href="https://github.com/concretecms-community-store/community_store_event_example" target="_blank" rel="noreferrer">https://github.com/concretecms-community-store/community_store_event_example</a></p><h3 id="slack-integration" tabindex="-1">Slack Integration <a class="header-anchor" href="#slack-integration" aria-label="Permalink to &quot;Slack Integration&quot;">​</a></h3><p>To hook into events and send notifications to Slack, try the package: <a href="https://github.com/a3020/slife_community_store" target="_blank" rel="noreferrer">https://github.com/a3020/slife_community_store</a> (note that this package was last updated in 2017, so may need updating to work with current versions).</p>`,30)])])}const u=t(n,[["render",o]]);export{k as __pageData,u as default};
